window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8ba179cae0e13122"]={"versions": [{"id": "FIG-8ba179cae0e13122", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic Platform Basissoftware-Moduls CanNm (CAN Network Management). Das Metamodell definiert die strukturelle Kanal-Konfiguration (<code>CanNmChannelConfig</code>) und verknüpft sie mit externen PDU-Definitionen (<code>Pdu</code> aus <code>EcucPdu</code>) sowie dem Kommunikationsmanager (<code>ComMChannel</code> aus <code>ComM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Konfigurationselemente:</p>\n<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Wurzel-Konfigurationscontainer pro CAN-NM-Kanal mit <code>postBuildChangeable = false</code>.\n</li><li>Subcontainer von <code>CanNmChannelConfig</code>:\n<ul class=\"fig-list\"><li><code>CanNmTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxConfirmationPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmRxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Beinhaltet den Parameter <code>CanNmRxPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmRxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmUserDataTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxUserDataPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxUserDataPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li></ul>\n</li><li>Externe Referenzen und Container:\n<ul class=\"fig-list\"><li><code>CanNmComMNetworkHandleRef</code> (<code>EcucSymbolicNameReferenceDef</code>): Referenz von <code>CanNmChannelConfig</code> auf den Zielcontainer <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*).\n</li><li><code>Pdu</code> (<code>EcucParamConfContainerDef</code> aus <code>EcucPdu</code>, Multiplizität 0..*, <code>postBuildChangeable = true</code>): Zentraler externer PDU-Container als Ziel für Sende-, Empfangs- und UserData-PDUs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzsemantik. Es modelliert die Deklarationsstruktur zur Generierungs- und Konfigurationszeit, über die PDU-Router-, CanIf- und ComM-Ressourcen logisch den NM-Kanälen zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für BSW-Generatoren und Konfigurationswerkzeuge:</p>\n<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code> ist nicht post-build-änderbar (<code>postBuildChangeable = false</code>).\n</li><li>Pro NM-Kanal muss mindestens eine Empfangs-PDU (<code>CanNmRxPdu</code>, 1..*) konfiguriert werden; Sende- und Nutzerdaten-Sende-PDUs (<code>CanNmTxPdu</code>, <code>CanNmUserDataTxPdu</code>) sind optional (0..1).\n</li><li>Alle PDU-IDs (<code>CanNmTxConfirmationPduId</code>, <code>CanNmRxPduId</code>, <code>CanNmTxUserDataPduId</code>) sind als 16-Bit-Ganzzahlen (0..65535) mit symbolischen Namen definiert.\n</li><li>Jede konfigurierte PDU-Referenz muss genau auf eine globale <code>Pdu</code> verweisen (Multiplizität 1..1).\n</li><li>Die Kanalbindung an ComM erfolgt über eine symbolische Referenz (<code>CanNmComMNetworkHandleRef</code>) auf einen definierten <code>ComMChannel</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3851565c87ae37be", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic Platform Basissoftware-Moduls CanNm (CAN Network Management). Das Metamodell definiert die strukturelle Kanal-Konfiguration (<code>CanNmChannelConfig</code>) und verknüpft sie mit externen PDU-Definitionen (<code>Pdu</code> aus <code>EcucPdu</code>) sowie dem Kommunikationsmanager (<code>ComMChannel</code> aus <code>ComM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Konfigurationselemente:</p>\n<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Wurzel-Konfigurationscontainer pro CAN-NM-Kanal.\n</li><li>Subcontainer von <code>CanNmChannelConfig</code>:\n<ul class=\"fig-list\"><li><code>CanNmTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxConfirmationPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmRxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Beinhaltet den Parameter <code>CanNmRxPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmRxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmUserDataTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxUserDataPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxUserDataPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li></ul>\n</li><li>Externe Referenzen und Container:\n<ul class=\"fig-list\"><li><code>CanNmComMNetworkHandleRef</code> (<code>EcucSymbolicNameReferenceDef</code>): Referenz von <code>CanNmChannelConfig</code> auf den Zielcontainer <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).\n</li><li><code>Pdu</code> (<code>EcucParamConfContainerDef</code> aus <code>EcucPdu</code>, Multiplizität 0..*): Zentraler externer PDU-Container als Ziel für Sende-, Empfangs- und UserData-PDUs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzsemantik. Es modelliert die Deklarationsstruktur zur Generierungs- und Konfigurationszeit, über die PDU-Router-, CanIf- und ComM-Ressourcen logisch den NM-Kanälen zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für BSW-Generatoren und Konfigurationswerkzeuge:</p>\n<ul class=\"fig-list\"><li><code>ComMChannel</code> ist in seiner oberen Multiplizität auf maximal 256 Kanäle beschränkt.\n</li><li>Pro NM-Kanal muss mindestens eine Empfangs-PDU (<code>CanNmRxPdu</code>, 1..*) konfiguriert werden; Sende- und Nutzerdaten-Sende-PDUs (<code>CanNmTxPdu</code>, <code>CanNmUserDataTxPdu</code>) sind optional (0..1).\n</li><li>Alle PDU-IDs (<code>CanNmTxConfirmationPduId</code>, <code>CanNmRxPduId</code>, <code>CanNmTxUserDataPduId</code>) sind als 16-Bit-Ganzzahlen (0..65535) mit symbolischen Namen definiert.\n</li><li>Jede konfigurierte PDU-Referenz muss genau auf eine globale <code>Pdu</code> verweisen (Multiplizität 1..1).\n</li><li>Die Kanalbindung an ComM erfolgt über eine symbolische Referenz (<code>CanNmComMNetworkHandleRef</code>) auf einen definierten <code>ComMChannel</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ee5d3e3f087a0116", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic Platform Basissoftware-Moduls CanNm (CAN Network Management). Das Metamodell definiert die strukturelle Kanal-Konfiguration (<code>CanNmChannelConfig</code>) und verknüpft sie mit externen PDU-Definitionen (<code>Pdu</code> aus <code>EcucPdu</code>) sowie dem Kommunikationsmanager (<code>ComMChannel</code> aus <code>ComM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Konfigurationselemente:</p>\n<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Wurzel-Konfigurationscontainer pro CAN-NM-Kanal.\n</li><li>Subcontainer von <code>CanNmChannelConfig</code>:\n<ul class=\"fig-list\"><li><code>CanNmTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxConfirmationPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmRxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Beinhaltet den Parameter <code>CanNmRxPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmRxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmUserDataTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxUserDataPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxUserDataPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li></ul>\n</li><li>Externe Referenzen und Container:\n<ul class=\"fig-list\"><li><code>CanNmComMNetworkHandleRef</code> (<code>EcucSymbolicNameReferenceDef</code>): Referenz von <code>CanNmChannelConfig</code> auf den Zielcontainer <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).\n</li><li><code>Pdu</code> (<code>EcucParamConfContainerDef</code> aus <code>EcucPdu</code>, Multiplizität 0..*): Zentraler externer PDU-Container als Ziel für Sende-, Empfangs- und UserData-PDUs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzsemantik. Es modelliert die Deklarationsstruktur zur Generierungs- und Konfigurationszeit, über die PDU-Router-, CanIf- und ComM-Ressourcen logisch den NM-Kanälen zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für BSW-Generatoren und Konfigurationswerkzeuge:</p>\n<ul class=\"fig-list\"><li><code>ComMChannel</code> ist in seiner oberen Multiplizität auf maximal 256 Kanäle beschränkt.\n</li><li>Pro NM-Kanal muss mindestens eine Empfangs-PDU (<code>CanNmRxPdu</code>, 1..*) konfiguriert werden; Sende- und Nutzerdaten-Sende-PDUs (<code>CanNmTxPdu</code>, <code>CanNmUserDataTxPdu</code>) sind optional (0..1).\n</li><li>Alle PDU-IDs (<code>CanNmTxConfirmationPduId</code>, <code>CanNmRxPduId</code>, <code>CanNmTxUserDataPduId</code>) sind als 16-Bit-Ganzzahlen (0..65535) mit symbolischen Namen definiert.\n</li><li>Jede konfigurierte PDU-Referenz muss genau auf eine globale <code>Pdu</code> verweisen (Multiplizität 1..1).\n</li><li>Die Kanalbindung an ComM erfolgt über eine symbolische Referenz (<code>CanNmComMNetworkHandleRef</code>) auf einen definierten <code>ComMChannel</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-193b1fa61226e266", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration) des AUTOSAR Classic Platform Basissoftware-Moduls CanNm (CAN Network Management). Das Metamodell definiert die strukturelle Kanal-Konfiguration (<code>CanNmChannelConfig</code>) und verknüpft sie mit externen PDU-Definitionen (<code>Pdu</code>) sowie dem Kommunikationsmanager (<code>ComMChannel</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in folgende Konfigurationselemente:</p>\n<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Wurzel-Konfigurationscontainer pro CAN-NM-Kanal.\n</li><li>Subcontainer von <code>CanNmChannelConfig</code>:\n<ul class=\"fig-list\"><li><code>CanNmTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxConfirmationPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmRxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..*): Beinhaltet den Parameter <code>CanNmRxPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmRxPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li><li><code>CanNmUserDataTxPdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1): Beinhaltet den Parameter <code>CanNmTxUserDataPduId</code> (<code>EcucIntegerParamDef</code>, Bereich 0..65535, <code>symbolicNameValue = true</code>) sowie die Referenz <code>CanNmTxUserDataPduRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..1) mit Ziel <code>Pdu</code>.\n</li></ul>\n</li><li>Externe Referenzen und Container:\n<ul class=\"fig-list\"><li><code>CanNmComMNetworkHandleRef</code> (<code>EcucReferenceDef</code> mit <code>requiresSymbolicNameValue = true</code>): Referenz von <code>CanNmChannelConfig</code> auf den Zielcontainer <code>ComMChannel</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..256).\n</li><li><code>Pdu</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..*): Zentraler externer PDU-Container als Ziel für Sende-, Empfangs- und UserData-PDUs.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Verhaltens- oder Sequenzsemantik. Es modelliert die Deklarationsstruktur zur Generierungs- und Konfigurationszeit, über die PDU-Router-, CanIf- und ComM-Ressourcen logisch den NM-Kanälen zugeordnet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für BSW-Generatoren und Konfigurationswerkzeuge:</p>\n<ul class=\"fig-list\"><li><code>ComMChannel</code> ist in seiner oberen Multiplizität auf maximal 256 Kanäle beschränkt.\n</li><li>Pro NM-Kanal muss mindestens eine Empfangs-PDU (<code>CanNmRxPdu</code>, 1..*) konfiguriert werden; Sende- und Nutzerdaten-Sende-PDUs (<code>CanNmTxPdu</code>, <code>CanNmUserDataTxPdu</code>) sind optional (0..1).\n</li><li>Alle PDU-IDs (<code>CanNmTxConfirmationPduId</code>, <code>CanNmRxPduId</code>, <code>CanNmTxUserDataPduId</code>) sind als 16-Bit-Ganzzahlen (0..65535) mit symbolischen Namen definiert.\n</li><li>Jede konfigurierte PDU-Referenz muss genau auf eine globale <code>Pdu</code> verweisen (Multiplizität 1..1).\n</li><li>Die Kanalbindung an ComM erfolgt über eine symbolische Referenz (<code>CanNmComMNetworkHandleRef</code>) auf einen definierten <code>ComMChannel</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8ba179cae0e13122", "to": "FIG-3851565c87ae37be", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CanNmChannelConfig</code>: <code>postBuildChangeable = false</code> wurde entfernt.\n</li><li><code>Pdu</code>: <code>postBuildChangeable = true</code> wurde entfernt.\n</li><li><code>ComMChannel</code>: <code>upperMultiplicity</code> wurde von <code>*</code> auf <code>256</code> geändert.\n</li></ul>"}, {"from": "FIG-3851565c87ae37be", "to": "FIG-ee5d3e3f087a0116", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ee5d3e3f087a0116", "to": "FIG-193b1fa61226e266", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>CanNmComMNetworkHandleRef</code>: Typbezeichnung von <code>EcucSymbolicNameReferenceDef</code> zu <code>EcucReferenceDef</code> mit Attribut <code>requiresSymbolicNameValue = true</code> geändert.\n</li><li><code>Pdu</code>: Herkunftshinweis <code>(from EcucPdu)</code> unterhalb des Containers wurde entfernt.\n</li><li><code>ComMChannel</code>: Herkunftshinweis <code>(from ComM)</code> unterhalb des Containers wurde abgeschnitten/entfernt.\n</li><li>Formatierung: Leerzeichen vor Doppelpunkten in den Containernamen vereinheitlicht/entfernt.\n</li></ul>"}]};
